import{_ as e,o as a,c as n,a0 as r}from"./chunks/framework.D7EjqxMK.js";const p=JSON.parse('{"title":"Agentic Coding 全景","description":"","frontmatter":{},"headers":[],"relativePath":"07-ai-coding/07_前沿趋势/01_Agentic_Coding全景.md","filePath":"07-ai-coding/07_前沿趋势/01_Agentic_Coding全景.md"}'),o={name:"07-ai-coding/07_前沿趋势/01_Agentic_Coding全景.md"};function i(d,t,s,l,g,h){return a(),n("div",null,[...t[0]||(t[0]=[r(`<h1 id="agentic-coding-全景" tabindex="-1">Agentic Coding 全景 <a class="header-anchor" href="#agentic-coding-全景" aria-label="Permalink to &quot;Agentic Coding 全景&quot;">​</a></h1><blockquote><p><strong>在知识图谱中的位置</strong>：模块七 · 07_前沿趋势 · 第 1 节 <strong>难度</strong>：⭐⭐⭐</p></blockquote><hr><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p><strong>Agentic Coding</strong> 是 AI 编程的下一个范式——AI Agent 不再只是&quot;补全代码&quot;，而是自主执行完整的开发任务：从理解需求、规划架构、编写代码、调试、测试到部署。</p><hr><h2 id="_2-agentic-coding-vs-传统-ai-编程" tabindex="-1">2. Agentic Coding vs 传统 AI 编程 <a class="header-anchor" href="#_2-agentic-coding-vs-传统-ai-编程" aria-label="Permalink to &quot;2. Agentic Coding vs 传统 AI 编程&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>传统 AI 编程:</span></span>
<span class="line"><span>  用户 → 补全建议/Chat → 用户审查 → 用户执行</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Agentic Coding:</span></span>
<span class="line"><span>  用户 → 描述任务 → Agent 自主执行（规划+编码+调试+测试） → 用户审查</span></span></code></pre></div><table tabindex="0"><thead><tr><th>维度</th><th>传统 AI 编程</th><th>Agentic Coding</th></tr></thead><tbody><tr><td><strong>自主性</strong></td><td>被动响应</td><td>自主执行完整流程</td></tr><tr><td><strong>上下文</strong></td><td>当前文件</td><td>整个代码库</td></tr><tr><td><strong>执行</strong></td><td>用户手动</td><td>Agent 自动执行</td></tr><tr><td><strong>复杂度</strong></td><td>单任务</td><td>多步骤协作</td></tr><tr><td><strong>工具</strong></td><td>IDE 内置</td><td>终端、浏览器、版本控制</td></tr></tbody></table><hr><h2 id="_3-核心-agent-能力" tabindex="-1">3. 核心 Agent 能力 <a class="header-anchor" href="#_3-核心-agent-能力" aria-label="Permalink to &quot;3. 核心 Agent 能力&quot;">​</a></h2><h3 id="_3-1-需求理解" tabindex="-1">3.1 需求理解 <a class="header-anchor" href="#_3-1-需求理解" aria-label="Permalink to &quot;3.1 需求理解&quot;">​</a></h3><p>Agent 理解自然语言描述的需求，拆解为可执行任务。</p><h3 id="_3-2-架构规划" tabindex="-1">3.2 架构规划 <a class="header-anchor" href="#_3-2-架构规划" aria-label="Permalink to &quot;3.2 架构规划&quot;">​</a></h3><p>Agent 设计代码架构、API 设计、数据库 Schema。</p><h3 id="_3-3-代码生成" tabindex="-1">3.3 代码生成 <a class="header-anchor" href="#_3-3-代码生成" aria-label="Permalink to &quot;3.3 代码生成&quot;">​</a></h3><p>Agent 生成完整代码（多文件、跨模块）。</p><h3 id="_3-4-调试" tabindex="-1">3.4 调试 <a class="header-anchor" href="#_3-4-调试" aria-label="Permalink to &quot;3.4 调试&quot;">​</a></h3><p>Agent 诊断 Bug、运行测试、自动修复。</p><h3 id="_3-5-测试" tabindex="-1">3.5 测试 <a class="header-anchor" href="#_3-5-测试" aria-label="Permalink to &quot;3.5 测试&quot;">​</a></h3><p>Agent 生成测试用例、运行测试、确保覆盖率。</p><h3 id="_3-6-部署" tabindex="-1">3.6 部署 <a class="header-anchor" href="#_3-6-部署" aria-label="Permalink to &quot;3.6 部署&quot;">​</a></h3><p>Agent 配置环境、构建、部署到目标平台。</p><hr><h2 id="_4-agentic-coding-的代表工具" tabindex="-1">4. Agentic Coding 的代表工具 <a class="header-anchor" href="#_4-agentic-coding-的代表工具" aria-label="Permalink to &quot;4. Agentic Coding 的代表工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>类型</th><th>核心能力</th></tr></thead><tbody><tr><td><strong>Cursor Composer</strong></td><td>IDE</td><td>跨文件生成 + 执行</td></tr><tr><td><strong>Claude Code</strong></td><td>CLI Agent</td><td>终端对话式开发</td></tr><tr><td><strong>OpenAI Codex CLI</strong></td><td>CLI Agent</td><td>自主编码 Agent</td></tr><tr><td><strong>Devin</strong></td><td>AI Agent</td><td>全自主开发</td></tr><tr><td><strong>GitHub Copilot Agent</strong></td><td>IDE</td><td>Explore/Task/Plan/Review</td></tr></tbody></table><hr><h2 id="_5-参考资料" tabindex="-1">5. 参考资料 <a class="header-anchor" href="#_5-参考资料" aria-label="Permalink to &quot;5. 参考资料&quot;">​</a></h2><ul><li><a href="https://cloud.tencent.com.cn/developer/article/2658138" target="_blank" rel="noreferrer">2026 Agentic Coding 全景图 (腾讯云)</a></li><li><a href="https://github.blog/ai-and-ml/github-copilot/how-to-build-reliable-ai-workflows-with-agentic-primitives-and-context-engineering/" target="_blank" rel="noreferrer">How to build reliable AI workflows with agentic primitives and context engineering (GitHub Blog)</a></li><li><a href="https://nick-tune.me/blog/2026-01-07-coding-agent-development-workflows/" target="_blank" rel="noreferrer">Coding Agent Development Workflows (nick-tune.me)</a></li><li><a href="https://sureprompts.com/blog/the-complete-guide-to-prompting-ai-coding-agents-2026" target="_blank" rel="noreferrer">The Complete Guide to Prompting AI Coding Agents (2026) (sureprompts.com)</a></li></ul>`,29)])])}const _=e(o,[["render",i]]);export{p as __pageData,_ as default};
